                    error "bad content-length"
                }
            }
            lappend flock_headers $flock_name $flock_value
        }
        if { [HTTP::method] eq "HEAD" || $flock_status == 204 || $flock_status == 304 } {
            set flock_length 0
        }
        set flock_body ""
        while { [string length $flock_body] < $flock_length } {
