            if { $flock_chunk eq "" } {
                error "answer body $flock_rstat"
            }
            append flock_body $flock_chunk
        }
    } flock_err]
    if { $flock_conn ne "" } {
        catch { close $flock_conn }
    }
    if { !$flock_failed && ($flock_status >= 500 || $flock_status < 200) } {
        set flock_failed 1
        set flock_err "status $flock_status"
    }
    if { $flock_failed } {
